def featurecard(f,full=False):
 ic,en,my,d,md,s,ms,example=f
 available=s in ('Demo','Demo sample','Available')
 url='/tools/' if ic=='grid' else '/chat/' if available else '/features/#'+ic
 ex=f'<div class="feature-example"><small>{tr("ILLUSTRATIVE PROMPT","နမူနာ PROMPT")}</small>{tr(example, {"write":"ရှင်းလင်းသော နိဒါန်းတစ်ခု ဖွဲ့စည်းရန် ကူညီပါ။","file":"စာရွက်စာတမ်း၏ အဓိကအချက်များကို အကျဉ်းချုပ်ပါ။","image":"ဤပုံပါ အချက်အလက်များကို ရှင်းပြပါ။","search":"ခေါင်းစဉ်ကို လေ့လာပြီး အရင်းအမြစ်ပြပါ။"}.get(ic,"ZOLAI GPT ၏ ဘာသာစကားများကို ပြောပြပါ။"),"p")}</div>' if full and example else ''
 return f'<article class="feature-card reveal" id="{ic}"><div class="card-top"><span class="feature-icon">{icon(ic)}</span>{badge(s,ms,"available" if available else "")}</div>{tr(en,my,"h3")}{tr(d,md,"p")}{ex}{link(url,"Explore tools" if ic=="grid" else "Try demo" if available else "View roadmap","ကိရိယာများကြည့်ရန်" if ic=="grid" else "Demo စမ်းရန်" if available else "အစီအစဉ်ကြည့်ရန်","card-link")}</article>'
def faq():
 qs=[('Is this connected to live AI?','Live AI နှင့် ချိတ်ဆက်ထားပါသလား။','Not yet. The workspace uses prewritten replies to demonstrate the interface. It cannot answer arbitrary questions with AI.','မချိတ်ဆက်ရသေးပါ။ Workspace တွင် UI စမ်းသပ်ရန် ကြိုတင်ရေးထားသော အဖြေများကို သုံးထားသည်။ မေးခွန်းအားလုံးကို AI ဖြင့် မဖြေနိုင်သေးပါ။'),('Which languages can I use?','ဘယ်ဘာသာစကားများကို သုံးနိုင်ပါသလဲ။','The website supports English and Myanmar. The chat demo also includes Zomi (Tedim) source-based sample replies.','ဝဘ်ဆိုက်တွင် အင်္ဂလိပ်နှင့် မြန်မာ ပါရှိသည်။ Chat demo တွင် Zomi (Tedim) နမူနာအဖြေများလည်း ပါသည်။'),('Do I need an account or a subscription?','အကောင့် သို့မဟုတ် subscription လိုပါသလား။','No account or payment is needed for the public demo and local tools. No paid plans are currently offered.','Public demo နှင့် local tools အတွက် အကောင့်နှင့် ငွေပေးချေမှု မလိုပါ။ လက်ရှိ အခပေးအစီအစဉ် မရှိပါ။'),('Where are conversations stored?','စကားဝိုင်းများကို ဘယ်နေရာမှာ သိမ်းပါသလဲ။','Demo conversations stay in the current tab memory and clear when you refresh. Export Markdown before leaving if you want a copy.','Demo စကားဝိုင်းများသည် လက်ရှိ tab မှတ်ဉာဏ်တွင်သာ ရှိပြီး refresh လုပ်လျှင် ပျောက်သွားမည်။ လိုအပ်ပါက Markdown ဖြင့် ထုတ်ယူထားပါ။'),('Can I analyse a document or image?','စာရွက်စာတမ်းနှင့် ပုံကို လေ့လာနိုင်ပါသလား။','AI document analysis, image understanding and live web research are Coming Soon. Local text attachments demonstrate the UI only.','AI ဖိုင်လေ့လာမှု၊ ပုံနားလည်မှုနှင့် live web research တို့ မရရှိသေးပါ။ Local စာသားဖိုင်တွဲခြင်းသည် UI နမူနာသာ ဖြစ်သည်။')]
 return '<div class="faq-list">'+''.join(f'<details><summary>{tr(q,mq)}<span aria-hidden="true">+</span></summary>{tr(a,ma,"p")}</details>' for q,mq,a,ma in qs)+'</div>'
