PAGES={'':('Your Intelligence, Amplified.',home),'features':('Features & availability',featurepage),'tools':('Tools directory',toolpage),'pricing':('Pricing & availability',pricing),'about':('About ZOLAI GPT',about),'help':('Help center',help),'contact':('Contact',contact)}
def build():
 for slug,(title,content) in PAGES.items():
  url='https://zolaigptofficial.com/'+(slug+'/' if slug else '')
  description='Explore ZOLAI GPT: a multilingual AI project, an interactive chat demo, browser-local tools and practical learning guides.'
  page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><meta name="theme-color" content="#080d19"/><title>{esc(title)} — ZOLAI GPT</title><meta name="description" content="{description}"/><meta name="google-adsense-account" content="ca-pub-7075005129832926"/><link rel="canonical" href="{url}"/><meta property="og:title" content="{esc(title)} — ZOLAI GPT"/><meta property="og:description" content="{description}"/><meta property="og:type" content="website"/><meta property="og:url" content="{url}"/><meta property="og:image" content="https://zolaigptofficial.com/assets/og-image.png"/><meta name="twitter:card" content="summary_large_image"/><link rel="icon" href="/assets/brand-mark.webp"/><link rel="preload" as="font" href="/assets/fonts/archivo-latin-variable.woff2" type="font/woff2" crossorigin/><link rel="stylesheet" href="/assets/css/platform.css?v=6"/><script type="module" src="/assets/js/platform.js?v=6"></script><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@type':'WebSite','name':'ZOLAI GPT','url':'https://zolaigptofficial.com/','inLanguage':['en','my']})}</script></head><body>{header()}<main id="main">{content}</main>{footer()}</body></html>'''
  path=ROOT/(slug+'/index.html' if slug else 'index.html');path.parent.mkdir(parents=True,exist_ok=True);path.write_text(page,encoding='utf-8')
 sitemap=['https://zolaigptofficial.com/'+(s+'/' if s else '') for s in PAGES]+['https://zolaigptofficial.com/guides/']
 (ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+u+'</loc></url>' for u in sitemap)+'</urlset>')
 print(f'Generated {len(PAGES)} pages and sitemap.')
if __name__=='__main__':build()
